-- Primary keys are UUID v7 generated by the application, with no database default (ADR 0002).
-- Fixed value sets use text + CHECK instead of Postgres ENUM types.
-- Every constraint is named explicitly so the application can identify each violation.
-- No updated_at yet: it depends on the sync strategy, which is not decided.

-- Internal users. Identity comes from the provider; we own the user (ADR 0004).
-- No email or profile data is stored: minimum data only (ADR 0004, rule 5).
CREATE TABLE users (
    id            uuid        NOT NULL,
    auth_provider text        NOT NULL,
    auth_subject  text        NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT users_pkey PRIMARY KEY (id),
    -- The provider identity is unique but never used as a primary or foreign key (ADR 0004, rule 1).
    CONSTRAINT users_auth_identity_key UNIQUE (auth_provider, auth_subject),
    CONSTRAINT users_auth_provider_check CHECK (auth_provider IN ('FIREBASE')),
    CONSTRAINT users_auth_subject_check CHECK (char_length(auth_subject) BETWEEN 1 AND 255)
);

CREATE TABLE projects (
    id         uuid        NOT NULL,
    name       text        NOT NULL,
    -- Attribution only, never authorization (ADR 0001, rule 1).
    created_by uuid        NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT projects_pkey PRIMARY KEY (id),
    CONSTRAINT projects_created_by_fkey FOREIGN KEY (created_by) REFERENCES users (id),
    CONSTRAINT projects_name_check CHECK (char_length(btrim(name)) BETWEEN 1 AND 100)
);

-- The only source of authorization (ADR 0001).
-- Own UUID primary key instead of a composite key (ADR 0002: same approach for every table).
CREATE TABLE project_members (
    id         uuid        NOT NULL,
    project_id uuid        NOT NULL,
    user_id    uuid        NOT NULL,
    role       text        NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT project_members_pkey PRIMARY KEY (id),
    CONSTRAINT project_members_project_id_fkey FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE CASCADE,
    CONSTRAINT project_members_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id),
    -- Also serves as the index for the project access check (project_id, user_id).
    CONSTRAINT project_members_project_user_key UNIQUE (project_id, user_id),
    -- Only two roles for now (ADR 0001, rule 3).
    CONSTRAINT project_members_role_check CHECK (role IN ('OWNER', 'MEMBER'))
);

-- Supports "list my projects" (lookup by user_id alone).
CREATE INDEX project_members_user_id_idx ON project_members (user_id);
